def trace(input_data):
    sess = TraceSession("Linear Scan", input_data,
                        pseudocode=["Initialize count = 0", "For each word, check if it starts with prefix", "Increment count if true", "Return count"])
    words = input_data["words"]
    prefix = input_data["prefix"]
    arr = sess.array("words", words)
    cnt = sess.scalar("count", 0)
    for i, word in enumerate(words):
        with sess.step(f"Check word {i}: \"{word}\""):
            arr.highlight(i, role="current")
            if word.startswith(prefix):
                cnt.set(cnt.value + 1, reason=f"\"{word}\" starts with \"{prefix}\"")
                arr.highlight(i, role="matched")
            else:
                sess.note(f"\"{word}\" does not start with \"{prefix}\"")
    sess.result(cnt.value)
    trace = sess.to_trace()
    for event in trace["events"]:
        targets = [t.get("id") for t in event.get("targets", [])]
        op = event.get("op")
        if op == "create" and "words" in targets:
            event["code_line"] = 2
        elif op == "create" and "count" in targets:
            event["code_line"] = 4
        elif op in ("highlight", "unhighlight") and "words" in targets:
            event["code_line"] = 5
        elif op == "set" and "count" in targets:
            event["code_line"] = 7
        elif event.get("role") == "answer":
            event["code_line"] = 8
        else:
            event["code_line"] = 5
    return trace
